void EffectUnitCard::paint (juce::Graphics& g)
{
    g.fillAll (juce::Colours::black);
    for (auto* each : built)
        each->setAlpha (lit ? 1.0f : dimmed);
}

good:
void EffectUnitCard::paint (juce::Graphics& g)
{
    g.setColour (juce::Colours::white);
    g.fillAll (juce::Colours::black);
}

void EffectUnitCard::setLit (bool on)
{
    lit = on;
    for (auto* each : built)
    {
        each->setAlpha (on ? 1.0f : dimmed);
        each->repaint();
    }
}

